                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                i, j = stack.pop()
                cells.append((i, j))
                for ni, nj in ((i-1, j), (i+1, j), (i, j-1), (i, j+1)):
                    if (0 <= ni < h and 0 <= nj < w and
                            (ni, nj) not in seen and grid[ni][nj] == color):
                        seen.add((ni, nj))
                        stack.append((ni, nj))
            comps.append((color, cells))

    for marker_color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        s = set(cells)
        if r0 == r1 or c0 == c1:
            continue

        # Identify the elbow and the directions of its two arms.
        elbow = None
        for er, ec in ((r0, c0), (r0, c1), (r1, c0), (r1, c1)):
            vertical = {(r, ec) for r in range(r0, r1 + 1)}
            horizontal = {(er, c) for c in range(c0, c1 + 1)}
            if s == vertical | horizontal:
                elbow = (er, ec)
                break
        if elbow is None:
            continue

