            mc = sum(c for r, c in obj) / len(obj)
            if target_r * (mr - er) > 0 and target_c * (mc - ec) > 0:
                candidates.append((abs(mr-er) + abs(mc-ec), obj))

        if candidates:
            obj = min(candidates, key=lambda x: x[0])[1]
            out = [row[:] for row in grid]
            for r, c in obj:
